import { charDisplayWidth } from '../surfaces/app-display-utils.js';

export const PATCH_PREVIEW_LABEL = 'Patch preview · literal text · control characters escaped';

/** Patch data is not model narration or Markdown. Keep every line; escape
 * terminal controls and bidi formatting rather than executing or hiding them. */
export function literalPatchRows(content: string, width: number): string[] {
  const limit = Math.max(2, Number.isFinite(width) ? Math.floor(width) : 80);
  const rows: string[] = [];
  for (const line of content.split('\n')) {
    const safe = Array.from(line, char => {
      const point = char.codePointAt(0)!;
      if (char === '\t') return '\\t';
      if (point < 32 || (point >= 127 && point <= 159)) return `\\x${point.toString(16).padStart(2, '0')}`;
      if ((point >= 0x202a && point <= 0x202e) || (point >= 0x2066 && point <= 0x2069)
        || point === 0x200e || point === 0x200f || point === 0x061c || point === 0x2028 || point === 0x2029) {
        return `\\u${point.toString(16).padStart(4, '0')}`;
      }
      return char;
    }).join('');
    let row = '';
    let columns = 0;
    for (const char of safe) {
      const size = charDisplayWidth(char);
      if (columns + size > limit && row) { rows.push(row); row = ''; columns = 0; }
      row += char;
      columns += size;
    }
    rows.push(row);
  }
  return rows;
}

